-- Preserves the original SQLite column names and constraints.
CREATE TABLE `aliases` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `alias` VARCHAR(255) NOT NULL, `aliasHash` VARCHAR(255) NOT NULL, `domain` VARCHAR(255) NOT NULL, `owner` VARCHAR(255) NOT NULL, `ownerPk` VARCHAR(255) NOT NULL, `assetAddress` VARCHAR(255), `mintTx` VARCHAR(255), `burnTx` VARCHAR(255), `bindingProof` TEXT, `nonce` VARCHAR(255), `price` VARCHAR(255), `expiresAt` INTEGER NOT NULL, `status` VARCHAR(255) NOT NULL DEFAULT 'active', `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `attachment_config` (`id` INTEGER PRIMARY KEY, `maxFileSizeBytes` INTEGER NOT NULL DEFAULT 10485760, `maxFileCount` INTEGER NOT NULL DEFAULT 5, `pricePerBytePerDay` VARCHAR(255) NOT NULL DEFAULT '0', `updatedAt` DATETIME NOT NULL, `createdAt` DATETIME NOT NULL);
CREATE TABLE `attachments` (`id` VARCHAR(255) PRIMARY KEY, `mailId` INTEGER NOT NULL, `encryptedName` TEXT NOT NULL, `encryptedMime` TEXT NOT NULL, `size` INTEGER NOT NULL, `hash` VARCHAR(255) NOT NULL, `content` BLOB NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `contacts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `sender` VARCHAR(255) NOT NULL, `receiver` VARCHAR(255) NOT NULL, `contact` TEXT NOT NULL, `namecard` VARCHAR(255) NOT NULL, `hash` VARCHAR(255), `size` INTEGER, `paymentTx` VARCHAR(255), `assetTx` VARCHAR(255), `asset` VARCHAR(255), `payment` VARCHAR(255), `credit` VARCHAR(255), `dividend` VARCHAR(255), `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, `deletedAt` DATETIME);
CREATE TABLE `domain_bindings` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `domain` VARCHAR(255) NOT NULL UNIQUE, `status` VARCHAR(255) NOT NULL DEFAULT 'pending', `challenge` VARCHAR(255), `domainKeyEnc` TEXT, `verifiedAt` INTEGER, `lastCheckedAt` INTEGER, `graceUntil` INTEGER, `aliasPrice` VARCHAR(255) NOT NULL DEFAULT '0', `renewPricePerYear` VARCHAR(255) NOT NULL DEFAULT '0', `minLength` INTEGER NOT NULL DEFAULT 4, `maxLength` INTEGER NOT NULL DEFAULT 32, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `envelopes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `address` VARCHAR(255) NOT NULL, `name` VARCHAR(255) NOT NULL, `price` VARCHAR(255) NOT NULL, `token` VARCHAR(255) NOT NULL, `retentionPeriod` INTEGER NOT NULL, `description` TEXT, `svg` TEXT, `enabled` TINYINT(1) NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `mails` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `subject` TEXT NOT NULL, `content` TEXT NOT NULL, `sender` VARCHAR(255) NOT NULL, `receiver` VARCHAR(255) NOT NULL, `envelope` VARCHAR(255) NOT NULL, `hash` VARCHAR(255) NOT NULL, `size` INTEGER NOT NULL, `paymentTx` VARCHAR(255), `assetTx` VARCHAR(255), `asset` VARCHAR(255), `payment` VARCHAR(255), `credit` VARCHAR(255), `dividend` VARCHAR(255), `expiredAt` DATETIME, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, `downloadAt` DATETIME, `deletedAt` DATETIME, `totalAttachmentSize` INTEGER DEFAULT 0, `attachmentCount` INTEGER DEFAULT 0, `attachmentStorageCost` VARCHAR(255) DEFAULT '0');
CREATE TABLE `namecards` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `address` VARCHAR(255) NOT NULL, `price` VARCHAR(255) NOT NULL, `token` VARCHAR(255) NOT NULL, `description` TEXT, `svg` TEXT, `enabled` TINYINT(1) NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE UNIQUE INDEX `aliases_alias_domain` ON `aliases` (`alias`, `domain`);
CREATE INDEX `aliases_alias_hash` ON `aliases` (`aliasHash`);
CREATE INDEX `aliases_owner` ON `aliases` (`owner`);
CREATE INDEX `attachments_mail_id` ON `attachments` (`mailId`);
